"""QA 240 C repro (generated by tools/qa/qa_c_walk.py): step_ROTATE: shows Off but Blender steps this transform by the increment (use_snap, INCREMENT, use_snap_rotate all on)

Run: ALLSET_SANDBOX=qa_c python tests/run.py --no-build -k __none__ --extra tools/qa/repro_c_s1_1.py
"""
from importlib.util import module_from_spec, spec_from_file_location
from pathlib import Path

_spec = spec_from_file_location('qa_c_walk', Path(__file__).resolve().parent / 'qa_c_walk.py')
walk = module_from_spec(_spec)
_spec.loader.exec_module(walk)

ACTIONS = [["click", "snap_LIVE"], ["click", "step_RESIZE", "ABSOLUTE"], ["click", "snap_LIVE"], ["click", "snap_GRID"], ["click", "step_ROTATE", "OFF"], ["click", "snap_GRID"]]
SIGNATURE = "I1:step_ROTATE: shows Off but Blender steps this transform by the increment (use_snap, INCREMENT, use_snap_rotate"


def test_repro():
    found = walk.Run().run([tuple(a) for a in ACTIONS])
    hits = [f for f in found if walk.signature(f[1], f[2]) == SIGNATURE]
    assert not hits, hits[0]
